import { STREAM_TRANSPORT_ERROR } from "./streaming"

const encoder = new TextEncoder()

function isAbort(error: unknown, signal?: AbortSignal): boolean {
  return (
    signal?.aborted === true
    || (error instanceof Error && error.name === "AbortError")
  )
}

function containsTerminalError(text: string): boolean {
  return (
    text.includes("event: error")
    || text.includes('"type":"error"')
    || text.includes('"type":"response.failed"')
  )
}

export function wrapResponsesStream(
  body: ReadableStream<Uint8Array>,
  signal?: AbortSignal,
): ReadableStream<Uint8Array> {
  const reader = body.getReader()
  const decoder = new TextDecoder()
  let inspectionBuffer = ""
  let terminalErrorSeen = false
  let abortListener: (() => void) | undefined

  function cleanup(): void {
    if (abortListener) signal?.removeEventListener("abort", abortListener)
  }

  return new ReadableStream<Uint8Array>({
    start() {
      abortListener = () => void reader.cancel(signal?.reason)
      signal?.addEventListener("abort", abortListener, { once: true })
    },
    async pull(controller) {
      try {
        const result = await reader.read()
        if (result.done) {
          cleanup()
          controller.close()
          return
        }
        inspectionBuffer = `${inspectionBuffer}${decoder.decode(result.value, {
          stream: true,
        })}`.slice(-1024)
        terminalErrorSeen ||= containsTerminalError(inspectionBuffer)
        controller.enqueue(result.value)
      } catch (error) {
        cleanup()
        if (isAbort(error, signal)) {
          controller.close()
          return
        }
        if (!terminalErrorSeen) {
          controller.enqueue(
            encoder.encode(
              `event: error\ndata: ${JSON.stringify({
                type: "error",
                code: STREAM_TRANSPORT_ERROR.code,
                message: STREAM_TRANSPORT_ERROR.message,
                param: null,
              })}\n\n`,
            ),
          )
        }
        controller.close()
      }
    },
    async cancel(reason) {
      cleanup()
      await reader.cancel(reason)
    },
  })
}

import type { Context } from "hono"
import type { SSEStreamingApi } from "hono/streaming"

import consola from "consola"
import { streamSSE } from "hono/streaming"

/**
 * Narrow a service result to its non-streaming form.
 *
 * Streaming services return an async iterable; non-streaming ones return a
 * plain response object. Test the property that actually defines the
 * distinction rather than a proxy for it: an earlier version checked for an own
 * `choices` property, which happened to work only because the iterator returned
 * by `events()` does not expose one (see POTENTIAL_FEATURES.md #3).
 */
export function isNonStreaming<T>(
  response: T,
): response is Exclude<T, AsyncIterable<unknown>> {
  return !(Symbol.asyncIterator in Object(response))
}

export interface StreamSSEOptions {
  /** Request signal; an abort on it means the client went away. */
  signal?: AbortSignal
  /** Label used when logging a client disconnect. */
  label: string
  /** Writes a format-specific terminal event for non-abort failures. */
  onError?: (stream: SSEStreamingApi, error: unknown) => Promise<void> | void
  /** Reports that the upstream already emitted an in-band terminal error. */
  hasTerminalError?: () => boolean
}

/**
 * Wrap an SSE producer so that a client disconnect ends the stream quietly.
 *
 * A disconnect shows up either as an already-aborted request signal or as an
 * `AbortError` thrown while the upstream stream is being consumed. Neither is a
 * failure worth surfacing, so the stream simply ends. Anything else is
 * rethrown.
 *
 * This is the single definition of what "the client went away" means; it
 * previously existed as five structurally identical copies across the two route
 * handlers.
 */
export function streamSSEWithAbort(
  c: Context,
  { signal, label, onError, hasTerminalError }: StreamSSEOptions,
  produce: (stream: SSEStreamingApi) => Promise<void>,
): Response {
  return streamSSE(c, async (stream) => {
    try {
      await produce(stream)
    } catch (error) {
      if (isClientAbort(error, signal)) {
        consola.debug(`${label} stream aborted by client`)
        return
      }
      consola.error(`${label} stream failed`, error)
      if (hasTerminalError?.()) return
      if (!onError) throw error
      try {
        await onError(stream, error)
      } catch (writeError) {
        consola.debug(
          `${label} terminal error event could not be written`,
          writeError,
        )
      }
    }
  })
}

/**
 * Whether an error ending a stream means the client went away.
 *
 * Exported because this predicate is the only real logic in this module, and
 * it is not observable through a route: swallowing and rethrowing produce the
 * same client-visible result (headers are already sent, so both end as HTTP
 * 200 with a partial body and a clean EOF). It therefore has to be tested
 * directly.
 */
export function isClientAbort(error: unknown, signal?: AbortSignal): boolean {
  return (
    signal?.aborted === true
    || (error instanceof Error && error.name === "AbortError")
  )
}

export const STREAM_TRANSPORT_ERROR = {
  type: "api_error",
  code: "stream_transport_error",
  message: "The upstream stream terminated unexpectedly.",
} as const

export async function writeOpenAIStreamError(
  stream: SSEStreamingApi,
): Promise<void> {
  await stream.writeSSE({
    data: JSON.stringify({
      error: {
        type: STREAM_TRANSPORT_ERROR.type,
        code: STREAM_TRANSPORT_ERROR.code,
        message: STREAM_TRANSPORT_ERROR.message,
        param: null,
      },
    }),
  })
}

import type { Context } from "hono"

import consola from "consola"
import { type SSEMessage } from "hono/streaming"

import { awaitApproval } from "~/lib/approval"
import { resolveEffort } from "~/lib/effort"
import { resolveEndpoint } from "~/lib/endpoint-routing"
import { checkRateLimit } from "~/lib/rate-limit"
import { state } from "~/lib/state"
import {
  isNonStreaming,
  streamSSEWithAbort,
  writeOpenAIStreamError,
} from "~/lib/streaming"
import { getTokenCount } from "~/lib/tokenizer"
import { isNullish } from "~/lib/utils"
import {
  createChatCompletions,
  type ChatCompletionChunk,
  type ChatCompletionsPayload,
} from "~/services/copilot/create-chat-completions"
import {
  createResponses,
  createResponsesStreamState,
  translateResponsesStreamEvent,
} from "~/services/copilot/create-responses"

export async function handleCompletion(c: Context) {
  await checkRateLimit(state)

  let payload = await c.req.json<ChatCompletionsPayload>()
  consola.debug("Request payload:", JSON.stringify(payload).slice(-400))

  // Find the selected model
  const selectedModel = state.models?.data.find(
    (model) => model.id === payload.model,
  )

  // Calculate and display token count
  try {
    if (selectedModel) {
      const tokenCount = await getTokenCount(payload, selectedModel)
      consola.info("Current token count:", tokenCount)
    } else {
      consola.warn("No model selected, skipping token count calculation")
    }
  } catch (error) {
    consola.warn("Failed to calculate token count:", error)
  }

  if (state.manualApprove) await awaitApproval()

  if (isNullish(payload.max_tokens)) {
    payload = {
      ...payload,
      max_tokens: selectedModel?.capabilities.limits.max_output_tokens,
    }
    consola.debug("Set max_tokens to:", JSON.stringify(payload.max_tokens))
  }

  const endpoint = resolveEndpoint(payload.model, state.models)
  const signal = c.req.raw.signal

  // Route to /responses for GPT-5.x and models that only support it
  if (endpoint === "/responses") {
    consola.debug(`Using /responses endpoint for model: ${payload.model}`)
    return handleResponsesEndpoint(c, payload, signal)
  }

  payload.reasoning_effort = resolveEffort({
    modelId: payload.model,
    requested: payload.reasoning_effort,
    cachedModels: state.models,
  })

  // Existing /chat/completions path
  const response = await createChatCompletions(payload, signal)

  if (isNonStreaming(response)) {
    consola.debug("Non-streaming response:", JSON.stringify(response))
    return c.json(response)
  }

  consola.debug("Streaming response")
  let terminalErrorSeen = false
  return streamSSEWithAbort(
    c,
    {
      signal,
      label: "chat-completions",
      onError: writeOpenAIStreamError,
      hasTerminalError: () => terminalErrorSeen,
    },
    async (stream) => {
      for await (const chunk of response) {
        consola.debug("Streaming chunk:", JSON.stringify(chunk))
        terminalErrorSeen ||= Boolean((chunk as ChatCompletionChunk).error)
        await stream.writeSSE(chunk as SSEMessage)
      }
    },
  )
}

async function handleResponsesEndpoint(
  c: Context,
  payload: ChatCompletionsPayload,
  signal?: AbortSignal,
) {
  const effort = resolveEffort({
    modelId: payload.model,
    requested: payload.reasoning_effort,
    cachedModels: state.models,
    defaultEffort: "medium",
  })
  const response = await createResponses(payload, effort, signal)

  if (isNonStreaming(response)) {
    consola.debug("Non-streaming /responses result:", JSON.stringify(response))
    return c.json(response)
  }

  consola.debug("Streaming /responses response")
  let terminalErrorSeen = false
  return streamSSEWithAbort(
    c,
    {
      signal,
      label: "/responses",
      onError: writeOpenAIStreamError,
      hasTerminalError: () => terminalErrorSeen,
    },
    async (stream) => {
      const streamState = createResponsesStreamState()

      for await (const rawEvent of response) {
        if (!rawEvent.data || rawEvent.data === "[DONE]") continue

        const parsed = JSON.parse(rawEvent.data) as Record<string, unknown>
        const eventType =
          rawEvent.event ?? (parsed.type as string | undefined) ?? ""

        const chunks = translateResponsesStreamEvent(
          { event: eventType, data: parsed },
          streamState,
        )

        for (const chunk of chunks) {
          consola.debug("Translated /responses chunk:", JSON.stringify(chunk))
          terminalErrorSeen ||= Boolean(chunk.error)
          await stream.writeSSE({
            data: JSON.stringify(chunk),
          })
        }
      }
    },
  )
}

import type { Context } from "hono"
import type { SSEStreamingApi } from "hono/streaming"

import consola from "consola"

import { awaitApproval } from "~/lib/approval"
import { resolveEffort } from "~/lib/effort"
import { resolveEndpoint } from "~/lib/endpoint-routing"
import { anthropicToCopilotModelId } from "~/lib/model-mapping"
import { checkRateLimit } from "~/lib/rate-limit"
import { state } from "~/lib/state"
import {
  isNonStreaming,
  STREAM_TRANSPORT_ERROR,
  streamSSEWithAbort,
} from "~/lib/streaming"
import {
  createChatCompletions,
  type ChatCompletionChunk,
} from "~/services/copilot/create-chat-completions"
import {
  createResponses,
  createResponsesStreamState,
  translateResponsesStreamEvent,
} from "~/services/copilot/create-responses"
import {
  forwardNativeMessagesNonStreaming,
  forwardNativeMessagesStreaming,
} from "~/services/copilot/forward-native-messages"

import {
  createAnthropicStreamState,
  type AnthropicMessagesPayload,
} from "./anthropic-types"
import {
  translateToAnthropic,
  translateToOpenAI,
} from "./non-stream-translation"
import {
  translateChunkToAnthropicEvents,
  translateErrorToAnthropicErrorEvent,
} from "./stream-translation"

const CONTEXT_1M_BETA = "context-1m-2025-08-07"

async function writeAnthropicStreamError(
  stream: SSEStreamingApi,
): Promise<void> {
  const event = translateErrorToAnthropicErrorEvent({
    type: STREAM_TRANSPORT_ERROR.type,
    message: STREAM_TRANSPORT_ERROR.message,
  })
  await stream.writeSSE({
    event: event.type,
    data: JSON.stringify(event),
  })
}

/**
 * Check if the request wants 1M context via the anthropic-beta header.
 * The Claude Agent SDK sets `anthropic-beta: context-1m-2025-08-07`
 * instead of appending [1m] to the model name.
 */
function detectWants1M(c: Context): boolean {
  const betaHeader = c.req.header("anthropic-beta") ?? ""
  return betaHeader.split(",").some((s) => s.trim() === CONTEXT_1M_BETA)
}

export async function handleCompletion(c: Context) {
  await checkRateLimit(state)

  const anthropicPayload = await c.req.json<AnthropicMessagesPayload>()
  consola.debug("Anthropic request payload:", JSON.stringify(anthropicPayload))

  if (state.manualApprove) {
    await awaitApproval()
  }

  // Check per-request 1M context: anthropic-beta header or global flag
  const wants1M = detectWants1M(c) || state.is1MContext

  const copilotModelId = anthropicToCopilotModelId(
    anthropicPayload.model,
    wants1M,
  )
  const endpoint = resolveEndpoint(copilotModelId, state.models)
  const signal = c.req.raw.signal

  // Native Anthropic passthrough for Claude models
  if (endpoint === "/v1/messages") {
    consola.debug(`Using native /v1/messages passthrough for ${copilotModelId}`)
    return handleNativePassthrough(c, anthropicPayload, wants1M, signal)
  }

  // Translate Anthropic → OpenAI format for non-Claude models
  const openAIPayload = translateToOpenAI(anthropicPayload)
  consola.debug(
    "Translated OpenAI request payload:",
    JSON.stringify(openAIPayload),
  )

  // /responses for GPT-5.x models (responses-only or preferred)
  if (endpoint === "/responses") {
    consola.debug(`Using /responses endpoint for ${copilotModelId}`)
    const effort = resolveEffort({
      modelId: copilotModelId,
      requested: anthropicPayload.output_config?.effort,
      cachedModels: state.models,
      defaultEffort: "medium",
    })
    return handleResponsesViaAnthropic({
      context: c,
      openAIPayload,
      effort,
      signal,
    })
  }

  // /chat/completions for legacy models
  openAIPayload.reasoning_effort = resolveEffort({
    modelId: copilotModelId,
    requested: anthropicPayload.output_config?.effort,
    cachedModels: state.models,
  })
  const response = await createChatCompletions(openAIPayload, signal)

  if (isNonStreaming(response)) {
    consola.debug(
      "Non-streaming response from Copilot:",
      JSON.stringify(response).slice(-400),
    )
    const anthropicResponse = translateToAnthropic(response)
    consola.debug(
      "Translated Anthropic response:",
      JSON.stringify(anthropicResponse),
    )
    return c.json(anthropicResponse)
  }

  consola.debug("Streaming response from Copilot")
  let terminalErrorSeen = false
  return streamSSEWithAbort(
    c,
    {
      signal,
      label: "/v1/messages chat-completions",
      onError: writeAnthropicStreamError,
      hasTerminalError: () => terminalErrorSeen,
    },
    async (stream) => {
      const streamState = createAnthropicStreamState()

      for await (const rawEvent of response) {
        consola.debug("Copilot raw stream event:", JSON.stringify(rawEvent))
        if (rawEvent.data === "[DONE]") {
          break
        }

        if (!rawEvent.data) {
          continue
        }

        const chunk = JSON.parse(rawEvent.data) as ChatCompletionChunk
        const events = translateChunkToAnthropicEvents(chunk, streamState)

        for (const event of events) {
          consola.debug("Translated Anthropic event:", JSON.stringify(event))
          terminalErrorSeen ||= event.type === "error"
          await stream.writeSSE({
            event: event.type,
            data: JSON.stringify(event),
          })
        }
      }
    },
  )
}

// eslint-disable-next-line max-params
async function handleNativePassthrough(
  c: Context,
  payload: AnthropicMessagesPayload,
  is1M: boolean,
  signal?: AbortSignal,
) {
  if (!payload.stream) {
    const response = await forwardNativeMessagesNonStreaming(
      payload,
      is1M,
      signal,
    )
    return c.json(response)
  }

  let terminalErrorSeen = false
  return streamSSEWithAbort(
    c,
    {
      signal,
      label: "/v1/messages native passthrough",
      onError: writeAnthropicStreamError,
      hasTerminalError: () => terminalErrorSeen,
    },
    async (stream) => {
      for await (const event of forwardNativeMessagesStreaming(
        payload,
        is1M,
        signal,
      )) {
        terminalErrorSeen ||= event.type === "error"
        await stream.writeSSE({
          event: event.type,
          data: JSON.stringify(event.data),
        })
      }
    },
  )
}

/**
 * Handle a request that needs the /responses endpoint but arrived via /v1/messages.
 * Flow: Anthropic payload → already translated to OpenAI → /responses → OpenAI response → Anthropic format.
 */
interface ResponsesViaAnthropicOptions {
  context: Context
  openAIPayload: Parameters<typeof createResponses>[0]
  effort?: string
  signal?: AbortSignal
}

async function handleResponsesViaAnthropic({
  context,
  openAIPayload,
  effort,
  signal,
}: ResponsesViaAnthropicOptions) {
  const response = await createResponses(openAIPayload, effort, signal)

  if (isNonStreaming(response)) {
    const anthropicResponse = translateToAnthropic(response)
    return context.json(anthropicResponse)
  }

  let terminalErrorSeen = false
  return streamSSEWithAbort(
    context,
    {
      signal,
      label: "/v1/messages /responses",
      onError: writeAnthropicStreamError,
      hasTerminalError: () => terminalErrorSeen,
    },
    async (stream) => {
      const responsesState = createResponsesStreamState()
      const anthropicState = createAnthropicStreamState()

      for await (const rawEvent of response) {
        if (!rawEvent.data || rawEvent.data === "[DONE]") continue

        const parsed = JSON.parse(rawEvent.data) as Record<string, unknown>
        const eventType =
          rawEvent.event ?? (parsed.type as string | undefined) ?? ""

        const chunks = translateResponsesStreamEvent(
          { event: eventType, data: parsed },
          responsesState,
        )

        for (const chunk of chunks) {
          const events = translateChunkToAnthropicEvents(chunk, anthropicState)
          for (const event of events) {
            terminalErrorSeen ||= event.type === "error"
            await stream.writeSSE({
              event: event.type,
              data: JSON.stringify(event),
            })
          }
        }
      }
    },
  )
}

import { Hono } from "hono"

import { copilotBaseUrl } from "~/lib/api-config"
import { copilotFetch } from "~/lib/copilot-fetch"
import { wrapResponsesStream } from "~/lib/responses-stream-wrapper"
import { state } from "~/lib/state"

export const responsesRoutes = new Hono()

responsesRoutes.post("/", async (c) => {
  let payload: Record<string, unknown>
  try {
    payload = await c.req.json<Record<string, unknown>>()
  } catch {
    return c.json(
      { error: { message: "Request body must be valid JSON" } },
      400,
    )
  }

  const modelId = typeof payload.model === "string" ? payload.model : ""
  if (!modelId) {
    return c.json(
      { error: { message: "Responses request requires model" } },
      400,
    )
  }
  if (payload.stream !== undefined && typeof payload.stream !== "boolean") {
    return c.json({ error: { message: "stream must be a boolean" } }, 400)
  }

  const model = state.models?.data.find((item) => item.id === modelId)
  if (!model?.supported_endpoints?.includes("/responses")) {
    return c.json(
      {
        error: {
          message: `Model ${modelId} does not advertise /responses support`,
        },
      },
      400,
    )
  }

  const upstream = await copilotFetch(`${copilotBaseUrl(state)}/responses`, {
    method: "POST",
    body: JSON.stringify(payload),
    signal: c.req.raw.signal,
  })

  const headers = new Headers()
  const contentType = upstream.headers.get("content-type")
  if (contentType) headers.set("content-type", contentType)
  for (const name of [
    "cache-control",
    "openai-processing-ms",
    "retry-after",
    "x-copilot-service-request-id",
    "x-github-request-id",
    "x-ratelimit-limit",
    "x-ratelimit-remaining",
    "x-ratelimit-reset",
  ]) {
    const value = upstream.headers.get(name)
    if (value) headers.set(name, value)
  }

  const responseBody =
    contentType?.startsWith("text/event-stream") && upstream.body ?
      wrapResponsesStream(upstream.body, c.req.raw.signal)
    : upstream.body

  return new Response(responseBody, {
    status: upstream.status,
    statusText: upstream.statusText,
    headers,
  })
})

import { describe, expect, it } from "bun:test"

import { wrapResponsesStream } from "~/lib/responses-stream-wrapper"

const encoder = new TextEncoder()

function throwingStream(firstChunk: string): ReadableStream<Uint8Array> {
  let sent = false
  return new ReadableStream({
    pull(controller) {
      if (!sent) {
        sent = true
        controller.enqueue(encoder.encode(firstChunk))
        return
      }
      controller.error(new Error("upstream exploded"))
    },
  })
}

describe("native Responses stream failure visibility", () => {
  it("preserves partial bytes then emits one terminal Responses error", async () => {
    const body = await new Response(
      wrapResponsesStream(
        throwingStream(
          'event: response.created\ndata: {"type":"response.created"}\n\n',
        ),
      ),
    ).text()

    expect(body).toContain("event: response.created")
    expect(body.match(/event: error/g)).toHaveLength(1)
    expect(body).toContain('"code":"stream_transport_error"')
    expect(body).toContain(
      '"message":"The upstream stream terminated unexpectedly."',
    )
  })

  it("actively cancels a pending upstream read on client abort", async () => {
    const controller = new AbortController()
    let cancelled = false
    const upstream = new ReadableStream<Uint8Array>({
      pull() {
        return new Promise(() => {})
      },
      cancel() {
        cancelled = true
      },
    })
    const reader = wrapResponsesStream(upstream, controller.signal).getReader()
    const pendingRead = reader.read()
    controller.abort()

    expect(await pendingRead).toEqual({ done: true, value: undefined })
    expect(cancelled).toBe(true)
  })

  it("does not duplicate an in-band error after transport failure", async () => {
    const body = await new Response(
      wrapResponsesStream(
        throwingStream(
          'event: error\ndata: {"type":"error","message":"provider failed"}\n\n',
        ),
      ),
    ).text()

    expect(body.match(/event: error/g)).toHaveLength(1)
    expect(body).toContain("provider failed")
    expect(body).not.toContain("stream_transport_error")
  })

  it("preserves successful bytes exactly", async () => {
    const expected = new Uint8Array([0, 1, 2, 127, 128, 255])
    const actual = new Uint8Array(
      await new Response(
        wrapResponsesStream(
          new ReadableStream({
            start(controller) {
              controller.enqueue(expected)
              controller.close()
            },
          }),
        ),
      ).arrayBuffer(),
    )

    expect(actual).toEqual(expected)
  })
})

/**
 * Client-visible behaviour of the streaming handlers when a stream ends early.
 *
 * NOTE ON WHAT THESE DO AND DO NOT PROVE. By the time a stream fails, the
 * response headers are already sent, so a swallowed abort and a rethrown error
 * look identical from outside: HTTP 200, a partial body, and a clean EOF. A
 * mutation forcing isClientAbort to return false leaves every test in this file
 * passing. So these pin the *client-visible* contract only; the swallow-versus-
 * rethrow decision is pinned directly in tests/streaming-helpers.test.ts.
 *
 * They are still worth having: they exercise all five streaming paths across
 * both handlers end to end, which is what made the consolidation of five
 * duplicated catch blocks into src/lib/streaming.ts verifiable as
 * behaviour-preserving.
 */
import { afterEach, beforeEach, describe, expect, it, mock } from "bun:test"

import type { ModelsResponse } from "~/services/copilot/get-models"

import { state } from "~/lib/state"
import { server } from "~/server"

const originalFetch = globalThis.fetch
const originalModels = state.models
const originalToken = state.copilotToken
const originalManualApprove = state.manualApprove

function model(id: string, endpoints: Array<string>) {
  return {
    id,
    name: id,
    object: "model",
    vendor: id.startsWith("claude-") ? "anthropic" : "openai",
    version: "1",
    preview: false,
    model_picker_enabled: true,
    supported_endpoints: endpoints,
    capabilities: {
      family: id,
      limits: { max_output_tokens: 64000 },
      object: "model_capabilities",
      supports: { tool_calls: true },
      tokenizer: "o200k_base",
      type: "chat",
    },
  }
}

const catalog = {
  object: "list",
  data: [
    model("claude-sonnet-5", ["/v1/messages", "/chat/completions"]),
    model("gpt-5.5", ["/responses", "/chat/completions"]),
    model("gpt-4.1", ["/chat/completions"]),
  ],
} as unknown as ModelsResponse

/**
 * An SSE response that yields one usable event and then throws an AbortError
 * mid-iteration, mimicking a client disconnect during streaming.
 */
function abortingStream(firstEvent: string): Response {
  const encoder = new TextEncoder()
  let sent = false
  const body = new ReadableStream<Uint8Array>({
    pull(controller) {
      if (!sent) {
        sent = true
        controller.enqueue(encoder.encode(`${firstEvent}\n\n`))
        return
      }
      const abortError = new Error("The operation was aborted")
      abortError.name = "AbortError"
      controller.error(abortError)
    },
  })
  return new Response(body, {
    headers: { "content-type": "text/event-stream" },
  })
}

/** An SSE response that fails mid-iteration for a reason that is NOT an abort. */
function failingStream(firstEvent: string): Response {
  const encoder = new TextEncoder()
  let sent = false
  const body = new ReadableStream<Uint8Array>({
    pull(controller) {
      if (!sent) {
        sent = true
        controller.enqueue(encoder.encode(`${firstEvent}\n\n`))
        return
      }
      controller.error(new Error("upstream exploded"))
    },
  })
  return new Response(body, {
    headers: { "content-type": "text/event-stream" },
  })
}

function mockFetch(body: () => Response) {
